import { execFile } from 'node:child_process';
import { accessSync, constants, statSync } from 'node:fs';
import { homedir } from 'node:os';
import { delimiter, join, resolve } from 'node:path';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);

export class CommandError extends Error {
  constructor(message: string, readonly code?: string | number, readonly stdout = '', readonly stderr = '') { super(message); }
}

function safeGitDiagnostic(value: string): string {
  return value
    .replace(/\u001b\[[0-9;]*m/g, '')
    .replace(/\b(?:github_pat_|gh[pousr]_)[a-zA-Z0-9_]+\b/gi, '[redacted]')
    .replace(/\bBearer\s+[^\s,;]+/gi, 'Bearer [redacted]')
    .replace(/\b(?:authorization|token|password|secret|api[-_ ]?key)\s*[:=]\s*[^\r\n]*/gi, '[credential redacted]')
    .replace(/https?:\/\/[^\s/@]+:[^\s/@]+@/gi, 'https://[redacted]@')
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(-500);
}

export interface AoBinaryOptions {
  aoBin?: string;
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  platform?: string;
  home?: string;
  bundleRoots?: string[];
}

export function resolveAoBinary(options: AoBinaryOptions = {}): string {
  const env = options.env ?? process.env;
  const cwd = options.cwd ?? process.cwd();
  const candidates = (env.PATH ?? '').split(delimiter).filter(Boolean).map((dir) => resolve(cwd, dir, 'ao'));
  for (const override of [env.TALLY_AO_BIN, options.aoBin]) if (override) candidates.push(resolve(cwd, override));
  if ((options.platform ?? process.platform) === 'darwin') {
    const suffix = 'Agent Orchestrator.app/Contents/Resources/daemon/ao';
    candidates.push(...(options.bundleRoots ?? ['/Applications', join(options.home ?? homedir(), 'Applications')]).map((root) => join(root, suffix)));
  }
  for (const candidate of candidates) {
    try {
      accessSync(candidate, constants.X_OK);
      if (statSync(candidate).isFile()) return candidate;
    } catch { /* Try the next explicit location. */ }
  }
  throw new CommandError(`Agent Orchestrator (AO) is required; looked in PATH (${env.PATH || 'empty'}), TALLY_AO_BIN (${env.TALLY_AO_BIN || 'unset'}), repo.aoBin (${options.aoBin || 'unset'}) and ${candidates.filter((path) => path.includes('.app/')).join(', ') || 'no app-bundle locations on this platform'}; install AO or set TALLY_AO_BIN to its executable path.`, 'ENOENT');
}

/** Resolve Entire's standard user-local install location even when the shell PATH omits it. */
export function resolveEntireBinary(options: Pick<AoBinaryOptions, 'platform' | 'home'> = {}): string {
  const platform = options.platform ?? process.platform;
  const home = options.home ?? homedir();
  const local = join(home, '.local', 'bin', platform === 'win32' ? 'entire.exe' : 'entire');
  try {
    accessSync(local, platform === 'win32' ? constants.F_OK : constants.X_OK);
    if (statSync(local).isFile()) return local;
  } catch { /* Fall back to the user's PATH. */ }
  return 'entire';
}

export async function runCommand(file: string, args: string[], options: AoBinaryOptions & { timeout?: number; maxBuffer?: number } = {}): Promise<{ stdout: string; stderr: string }> {
  const executable = file === 'ao' ? resolveAoBinary(options) : file === 'entire' ? resolveEntireBinary(options) : file;
  try {
    return await execFileAsync(executable, args, { cwd: options.cwd, env: options.env, timeout: options.timeout, maxBuffer: options.maxBuffer, encoding: 'utf8' });
  } catch (error) {
    const failure = error as { code?: string | number; signal?: string; stdout?: unknown; stderr?: unknown };
    const code = failure.code;
    const label = code ?? failure.signal ?? 'unknown error';
    const stderr = typeof failure.stderr === 'string' ? failure.stderr : '';
    const diagnostic = file === 'git' ? safeGitDiagnostic(stderr) : '';
    const operation = file === 'git' && args.includes('push') ? ' push'
      : file === 'git' && args.includes('commit') ? ' commit' : '';
    throw new CommandError(code === 'ENOENT'
      ? `${file} is required but could not be started; install it or add its executable to PATH${options.cwd ? `, and check that ${options.cwd} exists` : ''}.`
      : `${file}${operation} command failed (${label})${diagnostic ? `: ${diagnostic}` : '; check the command in your terminal before retrying.'}`, code,
      typeof failure.stdout === 'string' ? failure.stdout : '', stderr);
  }
}
import { CommandError } from './command.js';

/** Read/write the full daemon config; the CLI mirror omits fields such as effort. */
export async function aoProjectCommand(args: string[], fetchImpl: typeof fetch = fetch): Promise<{ stdout: string; stderr: string }> {
  const editing = args[1] === 'set-config';
  const id = encodeURIComponent(args[2]!);
  const response = await fetchImpl(`http://127.0.0.1:3001/api/v1/projects/${id}${editing ? '/config' : ''}`, {
    method: editing ? 'PUT' : 'GET',
    ...(editing ? { headers: { 'content-type': 'application/json' }, body: JSON.stringify({ config: JSON.parse(args[args.indexOf('--config-json') + 1]!) }) } : {}),
    signal: AbortSignal.timeout(10_000),
  }).catch(() => { throw new CommandError('AO project API could not be reached; start AO and retry.'); });
  if (!response.ok) throw new CommandError(`AO project ${args[1]} failed: HTTP ${response.status}; check AO is running before retrying.`);
  return { stdout: JSON.stringify(await response.json()), stderr: '' };
}
import type { Tier } from '../schema/types.js';
import type { InitCommandRunner } from './init.js';
import { createHash } from 'node:crypto';

export type Harness = Tier['harness'];
export const AO_HARNESS_PERMISSIONS = { codex: 'auto', 'claude-code': 'default' } as const;
export type AoHarnessPermissionModes = Partial<Record<Harness, 'auto' | 'default'>>;
export interface HarnessStatus { harness: Harness; installed: boolean; signedIn: boolean; detail: string; fix: string }

/** CLI-owned status only: never inspect credential files or invoke inference. */
export async function checkHarness(harness: Harness, command: InitCommandRunner, cwd?: string): Promise<HarnessStatus> {
  const file = harness === 'claude-code' ? 'claude' : 'codex';
  const fix = harness === 'claude-code' ? 'claude auth login' : 'codex login';
  try { await command(file, ['--version'], { cwd }); }
  catch { return { harness, installed: false, signedIn: false, detail: `${file} is not installed or could not run. Install it before using ${harness} tiers.`, fix: `Install ${harness === 'claude-code' ? 'Claude Code (https://code.claude.com/docs/en/setup)' : 'Codex CLI (https://developers.openai.com/codex/cli/)'} and then run ${fix}.` }; }
  try {
    const output = await command(file, harness === 'claude-code' ? ['auth', 'status'] : ['login', 'status'], { cwd });
    const signedIn = harness === 'claude-code' ? JSON.parse(output.stdout).loggedIn === true
      : /\blogged in\b/i.test(`${output.stdout}\n${output.stderr}`) && !/\bnot logged in\b/i.test(`${output.stdout}\n${output.stderr}`);
    return { harness, installed: true, signedIn, detail: signedIn ? `${file} is installed and signed in. Model access was not probed.` : `${file} is signed out or its sign-in status could not be verified.`, fix };
  } catch { return { harness, installed: true, signedIn: false, detail: `${file} is signed out or its sign-in status could not be verified`, fix }; }
}

export function claudeAllowList(test: { command: string; setupCommand?: string }): string[] {
  const commands = ['git add *', 'git commit *', 'git status', 'git status *', 'git diff', 'git diff *'];
  return [...new Set(['Edit(./**)', 'Write(./**)', ...commands.map(value => `Bash(${value})`), ...claudeScripts(test).map(script => script.rule)])];
}

export function claudeScripts(test: { command: string; setupCommand?: string }): Array<{ name: 'test' | 'setup'; contents: string; rule: string }> {
  const commands = [test.command, ...(test.setupCommand ? [test.setupCommand] : [])];
  if (commands.some(value => /[\r\n]/.test(value))) throw new Error('Claude allow-list needs single-line test and setup commands');
  if (commands.some(value => value.includes('\0'))) throw new Error('Claude script commands cannot contain NUL');
  return commands.map((command, index) => {
    const name = index === 0 ? 'test' as const : 'setup' as const;
    const contents = `#!/bin/sh\nset -e\n${command}\n`;
    const hash = createHash('sha256').update(contents).digest('hex');
    return { name, contents, rule: `Bash({{tally.${name}Script:${hash}}})` };
  });
}

export function requireClaudeScriptConsent(allow: string[] | undefined, test: { command: string; setupCommand?: string }): asserts allow is string[] {
  const expected = claudeAllowList(test);
  if (!allow?.length || allow.length !== expected.length || expected.some(rule => !allow.includes(rule))) {
    throw new Error('Claude Code script consent is missing or outdated (old raw-command rules do not authorize scripts); re-run tally init to review and approve the current test/setup script contents.');
  }
}
import { loadEnv } from '../engine/env.js';
import { workerCorrelationPrefix } from '../engine/worker-correlation.js';
import type { IntegrationState } from '../schema/types.js';
import type { FailureSpan, FailureTraceContext, FailureTracePort } from '../agent/failure.js';

export interface WorkerTraceReadContext {
  runId: string;
  taskId: string;
  attempt: number;
  nativeSessionId?: string | null;
  traceId?: string | null;
}

export interface WorkerTraceReaderPort {
  verifyFor(context: WorkerTraceReadContext): Promise<string | null>;
  status?(): IntegrationState;
}

interface TraceRecord {
  traceId?: string;
  sessionId?: string;
  workflowName?: string;
  traceName?: string;
}

class TraceProjectionPending extends Error {
  constructor(readonly retryAfterMs: number | null) {
    super('Neatlogs has not finished building this trace span projection.');
    this.name = 'TraceProjectionPending';
  }
}

function retryAfterMs(response: Response): number | null {
  const value = response.headers.get('retry-after');
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds) && seconds >= 0) return Math.min(10_000, seconds * 1000);
  const date = Date.parse(value);
  return Number.isFinite(date) ? Math.min(10_000, Math.max(0, date - Date.now())) : null;
}

function matches(trace: TraceRecord, context: WorkerTraceReadContext): boolean {
  if (!trace.sessionId || trace.sessionId === context.runId || (context.nativeSessionId && trace.sessionId !== context.nativeSessionId)) return false;
  return [trace.workflowName, trace.traceName].some(name => {
    if (!name) return false;
    if (name.startsWith(workerCorrelationPrefix(context.runId, context.taskId, context.attempt))) return true;
    const legacy = /Tally run ([^,]+), task ([^,]+), attempt (\d+)(?:[:\s]|$)/.exec(name);
    return legacy?.[1] === context.runId && legacy[2] === context.taskId && Number(legacy[3]) === context.attempt;
  });
}

export class NeatlogsWorkerTraceReader implements WorkerTraceReaderPort, FailureTracePort {
  private readonly env: Record<string, string>;
  private readonly fetchImpl: typeof fetch;
  private readonly endpoint: string;
  private readonly retries: number;
  private readonly retryDelayMs: number;
  private state: IntegrationState = { status: 'ok', detail: null };

  constructor(options: { env?: Record<string, string>; fetch?: typeof fetch; endpoint?: string; retries?: number; retryDelayMs?: number } = {}) {
    this.env = options.env ?? loadEnv();
    this.fetchImpl = options.fetch ?? fetch;
    this.endpoint = options.endpoint ?? 'https://app.neatlogs.com/api/v1/public';
    this.retries = options.retries ?? 6;
    this.retryDelayMs = options.retryDelayMs ?? 500;
  }

  status(): IntegrationState { return this.state; }

  async failureFor(context: FailureTraceContext): Promise<{ traceId: string; spans: FailureSpan[] } | null> {
    const id = await this.verifyFor(context);
    if (!id) return null;
    const spans: FailureSpan[] = [];
    let cursor: string | undefined;
    const seen = new Set<string>();
    for (let page = 0; page < 5; page++) {
      const query = new URLSearchParams({ limit: '50', ...(cursor ? { cursor } : {}) });
      const body = await this.readFailureSpans(id, query);
      if (!Array.isArray(body?.data?.spans)) return null;
      for (const span of body.data.spans) {
        const text = (value: unknown) => typeof value === 'string' ? value : '';
        spans.push({
          id: text(span.spanId), name: text(span.spanName ?? span.name), type: text(span.spanType),
          status: text(span.status), error: text(span.errorMessage), startedAt: text(span.startedAt),
        });
      }
      if (!body.data.page?.hasMore) return { traceId: id, spans };
      cursor = body.data.page.nextCursor;
      if (!cursor || seen.has(cursor)) return null;
      seen.add(cursor);
    }
    // Partial history cannot prove that an early denial was unrecovered.
    return null;
  }

  private fail(detail: string): void {
    this.state = { status: 'missing', detail };
  }

  private async readFailureSpans(id: string, query: URLSearchParams): Promise<{
    data?: { spans?: Record<string, unknown>[]; page?: { hasMore?: boolean; nextCursor?: string } };
  } | null> {
    for (let retry = 0; retry < this.retries; retry++) {
      try {
        const body = await this.read(`/traces/${id}/spans?${query}`) as {
          data?: { spans?: Record<string, unknown>[]; page?: { hasMore?: boolean; nextCursor?: string } };
        } | null;
        if (body) this.state = { status: 'ok', detail: null };
        return body;
      } catch (error) {
        if (!(error instanceof TraceProjectionPending)) throw error;
        this.state = { status: 'ok', detail: 'Neatlogs is still indexing this worker trace; Tally retried the span read.' };
        if (retry + 1 < this.retries) {
          const backoff = Math.min(5000, this.retryDelayMs * (2 ** retry));
          await new Promise(resolve => setTimeout(resolve, error.retryAfterMs ?? backoff));
        }
      }
    }
    this.state = { status: 'ok', detail: 'Neatlogs is still indexing this worker trace; failure-span analysis is temporarily unavailable.' };
    return null;
  }

  async verifyFor(context: WorkerTraceReadContext): Promise<string | null> {
    this.state = { status: 'ok', detail: null };
    if (!this.env.NEATLOGS_TOKEN || !this.env.NEATLOGS_PROJECT_ID) {
      this.fail('Neatlogs worker trace read-back needs NEATLOGS_TOKEN and NEATLOGS_PROJECT_ID in ~/.tally/.env.');
      return null;
    }
    for (let retry = 0; retry < this.retries; retry++) {
      let retryDelay: number | null = null;
      try {
        const candidates = context.traceId ? [context.traceId] : await this.discover(context);
        if (!candidates.length && this.state.status === 'ok') {
          this.fail('No correlated worker trace found in up to 250 recent traces (5 pages at 50/page); check Neatlogs hook trust/setup and NEATLOGS_PROJECT_ID.');
        }
        for (const id of candidates) {
          if (!/^[0-9a-f]{32}$/i.test(id)) continue;
          const detail = await this.read(`/traces/${id}`) as { data?: TraceRecord } | null;
          if (!detail?.data || detail.data.traceId !== id || !matches(detail.data, context)) continue;
          const spans = await this.read(`/traces/${id}/spans`) as { data?: { spans?: unknown[] } } | null;
          // A trace-list stub/app shell is not delivery proof. Killed turns may have
          // zero aggregate tokens yet still have readable tool spans.
          if (Array.isArray(spans?.data?.spans) && spans.data.spans.length > 0) {
            this.state = { status: 'ok', detail: null };
            return id;
          }
          if (this.state.status === 'ok') this.fail(`Neatlogs trace ${id} matched the worker but has no readable spans yet; retry after ingestion finishes.`);
        }
      } catch (error) {
        if (error instanceof TraceProjectionPending) {
          retryDelay = error.retryAfterMs;
          this.state = { status: 'ok', detail: 'Neatlogs is still indexing this worker trace; Tally retried the span read.' };
        } else {
          const name = error instanceof Error ? error.name : 'unknown error';
          this.fail(name === 'AbortError' || name === 'TimeoutError'
            ? 'Neatlogs worker trace read-back timed out; check connectivity and retry.'
            : `Neatlogs worker trace read-back request failed (${name}); check connectivity and retry.`);
        }
      }
      if (retry + 1 < this.retries) {
        const backoff = Math.min(5000, this.retryDelayMs * (2 ** retry));
        await new Promise(resolve => setTimeout(resolve, retryDelay ?? backoff));
      }
    }
    return null;
  }

  private async discover(context: WorkerTraceReadContext): Promise<string[]> {
    let cursor: string | undefined;
    const ids: string[] = [];
    for (let page = 0; page < 5; page++) {
      const query = new URLSearchParams({ limit: '50', ...(cursor ? { cursor } : {}) });
      const body = await this.read(`/traces?${query}`) as { data?: { traces?: TraceRecord[]; page?: { nextCursor?: string; hasMore?: boolean } } } | null;
      if (!Array.isArray(body?.data?.traces)) break;
      for (const trace of body.data.traces) if (matches(trace, context) && trace.traceId) ids.push(trace.traceId);
      if (ids.length || !body.data.page?.hasMore || !body.data.page.nextCursor) break;
      cursor = body.data.page.nextCursor;
    }
    return ids;
  }

  private async read(path: string): Promise<unknown | null> {
    const response = await this.fetchImpl(`${this.endpoint}${path}`, {
      headers: { Authorization: `Bearer ${this.env.NEATLOGS_TOKEN}`, 'x-project-id': this.env.NEATLOGS_PROJECT_ID! },
      signal: AbortSignal.timeout(10000),
    });
    if (!response.ok) {
      const operation = path.includes('/spans') ? 'worker span read-back' : 'worker trace read-back';
      if (response.status === 409 && path.includes('/spans')) throw new TraceProjectionPending(retryAfterMs(response));
      const detail = response.status === 401
        ? `Neatlogs ${operation} was unauthorized (HTTP 401); check NEATLOGS_TOKEN and its project binding.`
        : response.status === 403
          ? `Neatlogs ${operation} was forbidden (HTTP 403); check the token's observability:read scope and project role.`
          : response.status === 404
            ? `Neatlogs ${operation} returned HTTP 404; confirm the selected project and retry after ingestion.`
            : response.status === 429
              ? `Neatlogs ${operation} was rate limited (HTTP 429); retry after a short delay.`
              : response.status >= 500
                ? `Neatlogs ${operation} is temporarily unavailable (HTTP ${response.status}); retry later.`
                : `Neatlogs ${operation} failed (HTTP ${response.status}).`;
      this.fail(detail);
      return null;
    }
    return response.json();
  }
}
  }

  discoveryState(): OAuthDiscoveryState | undefined {
    return this.store.read().discoveryState;
  }

  invalidateCredentials(scope: 'all' | 'client' | 'tokens' | 'verifier' | 'discovery'): void {
    const current = this.store.read();
    if (scope === 'all') return this.store.write({});
    if (scope === 'client') delete current.clientInformation;
    if (scope === 'tokens') delete current.tokens;
    if (scope === 'verifier') delete current.codeVerifier;
    if (scope === 'discovery') delete current.discoveryState;
    this.store.write(current);
  }
}

class SdkCfoaiMcpClient implements CfoaiMcpClient {
  private readonly client = new Client({ name: 'tally', version: '0.1.0' });
  private readonly transport: StreamableHTTPClientTransport;
      rejectCode(new Error('cfo.ai OAuth callback did not include a code'));
    }
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
