export function claudeAllowList(test: { command: string; setupCommand?: string }): string[] {
  const commands = ['git add *', 'git commit *', 'git status', 'git status *', 'git diff', 'git diff *'];
  return [...new Set(['Edit(./**)', 'Write(./**)', ...commands.map(value => `Bash(${value})`), ...claudeScripts(test).map(script => script.rule)])];
}

export function claudeScripts(test: { command: string; setupCommand?: string }): Array<{ name: 'test' | 'setup'; contents: string; rule: string }> {
  const commands = [test.command, ...(test.setupCommand ? [test.setupCommand] : [])];
  if (commands.some(value => /[\r\n]/.test(value))) throw new Error('Claude allow-list needs single-line test and setup commands');
  if (commands.some(value => value.includes('\0'))) throw new Error('Claude script commands cannot contain NUL');
  return commands.map((command, index) => {
    const name = index === 0 ? 'test' as const : 'setup' as const;
    const contents = `#!/bin/sh\nset -e\n${command}\n`;
    const hash = createHash('sha256').update(contents).digest('hex');
    return { name, contents, rule: `Bash({{tally.${name}Script:${hash}}})` };
  });
}

export function requireClaudeScriptConsent(allow: string[] | undefined, test: { command: string; setupCommand?: string }): asserts allow is string[] {
  const expected = claudeAllowList(test);
  if (!allow?.length || allow.length !== expected.length || expected.some(rule => !allow.includes(rule))) {
    throw new Error('Claude Code script consent is missing or outdated (old raw-command rules do not authorize scripts); re-run tally init to review and approve the current test/setup script contents.');
  }
}
import { loadEnv } from '../engine/env.js';
import { workerCorrelationPrefix } from '../engine/worker-correlation.js';
import type { IntegrationState } from '../schema/types.js';
import type { FailureSpan, FailureTraceContext, FailureTracePort } from '../agent/failure.js';

export interface WorkerTraceReadContext {
  runId: string;
  taskId: string;
  attempt: number;
  nativeSessionId?: string | null;
  traceId?: string | null;
}

export interface WorkerTraceReaderPort {
  verifyFor(context: WorkerTraceReadContext): Promise<string | null>;
  status?(): IntegrationState;
}

interface TraceRecord {
  traceId?: string;
  sessionId?: string;
  workflowName?: string;
  traceName?: string;
}

class TraceProjectionPending extends Error {
  constructor(readonly retryAfterMs: number | null) {
    super('Neatlogs has not finished building this trace span projection.');
    this.name = 'TraceProjectionPending';
  }
}

function retryAfterMs(response: Response): number | null {
  const value = response.headers.get('retry-after');
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds) && seconds >= 0) return Math.min(10_000, seconds * 1000);
  const date = Date.parse(value);
  return Number.isFinite(date) ? Math.min(10_000, Math.max(0, date - Date.now())) : null;
}

function matches(trace: TraceRecord, context: WorkerTraceReadContext): boolean {
  if (!trace.sessionId || trace.sessionId === context.runId || (context.nativeSessionId && trace.sessionId !== context.nativeSessionId)) return false;
  return [trace.workflowName, trace.traceName].some(name => {
    if (!name) return false;
    if (name.startsWith(workerCorrelationPrefix(context.runId, context.taskId, context.attempt))) return true;
    const legacy = /Tally run ([^,]+), task ([^,]+), attempt (\d+)(?:[:\s]|$)/.exec(name);
    return legacy?.[1] === context.runId && legacy[2] === context.taskId && Number(legacy[3]) === context.attempt;
  });
}

export class NeatlogsWorkerTraceReader implements WorkerTraceReaderPort, FailureTracePort {
